// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/utils/Counters.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./LotRoom.sol";

// @title Auction: static encrypted metadata per lot
contract Auction is ERC721, Ownable, ReentrancyGuard {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;
    address[] public lots;

    bytes private _auctionStaticData;

    event LotsListUpdated(address[] newLots);

    constructor(bytes memory auctionData) ERC721("Japanese Auction", "LOTS") {
        _auctionStaticData = auctionData;
    }

    /// @notice Get static encrypted data
    function getAuctionData() external view returns (bytes memory) {
        return _auctionStaticData;
    }

    /// @notice Create auction lot with static encrypted data
    function createLot(
        uint256 ethStep,
        uint256 startingPrice
    ) external returns (address) {
        _tokenIds.increment();
        uint256 tokenId = _tokenIds.current();

        // Deploy handler and auction room
        ERC721Handler handler = new ERC721Handler(address(this), tokenId, msg.sender);
        LotRoom lot = new LotRoom(handler, tokenId, ethStep, startingPrice, msg.sender);
        address lotAddress = address(lot);

        // Store lot and mint NFT to handler
        lots.push(lotAddress);
        _mint(address(handler), tokenId);
        emit LotsListUpdated(lots);

        return lotAddress;
    }

    function isValidLot(address lotAddress) public view returns (bool) {
        for (uint256 i = 0; i < lots.length; i++) {
            if (lots[i] == lotAddress) return true;
        }
        return false;
    }

    /// @notice Remove a lot; only owner
    function removeLot(address lotAddress) external onlyOwner nonReentrant {
        require(isValidLot(lotAddress), "Lot doesn't exist");
        uint256 length = lots.length;
        for (uint256 i = 0; i < length; i++) {
            if (lots[i] == lotAddress) {
                lots[i] = lots[length - 1];
                lots.pop();
                break;
            }
        }
        emit LotsListUpdated(lots);
    }
}

contracts/ERC721Handler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

// @title ERC721 proxy that stores dynamic encrypted metadata
contract ERC721Handler is IERC721Receiver {
    address private _erc721Contract;
    uint256 private _tokenID;
    address private _creator;
    address private _lotRoom;

    bytes[] private _encryptedHistory;
    event DataAppended(uint256 indexed tokenId, bytes encryptedData);

    constructor(address erc721Contract, uint256 tokenID, address creator) {
        _erc721Contract = erc721Contract;
        _tokenID = tokenID;
        _creator = creator;
    }

    // @notice Called by LotRoom to initialize lotRoom address
    function setLotRoom(address lotRoom) external {
        require(_lotRoom == address(0), "Already initialized");
        require(msg.sender == _creator, "Only creator");
        _lotRoom = lotRoom;
    }

    // @notice Append new encrypted data; only LotRoom contract can call
    function appendData(bytes calldata newData) external {
        require(msg.sender == _lotRoom, "Not authorized");
        _encryptedHistory.push(newData);
        emit DataAppended(_tokenID, newData);
    }

    // @notice Get full history; only owner of NFT
    function getDataHistory() external view returns (bytes[] memory) {
        return _encryptedHistory;
    }

    // @notice Get latest encrypted data; only owner
    function getLatestData() external view returns (bytes memory) {
        return _encryptedHistory[_encryptedHistory.length - 1];
    }

    // @notice Transfer NFT to new owner
    function transfer(address to) external {
        IERC721(_erc721Contract).safeTransferFrom(address(this), to, _tokenID);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    // @notice Check ownership
    function isOwner(address account) external view returns (bool) {
        return IERC721(_erc721Contract).ownerOf(_tokenID) == account;
    }
}

contracts/LotRoom.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./ERC721Handler.sol";
import "./RoomHandler.sol";

/// @title Auction logic per lot, with token metadata updates
contract LotRoom is ReentrancyGuard {
    uint256 public tokenID;
    uint256 public initBlock;
    uint256 public finalBlock;
    uint256 public blockStep = 4;
    uint256 public waitingBlocks = 4;
    uint256 public ethStep;
    uint256 public price;
    uint256 public deposit = 0.01 ether;

    address public owner;
    ERC721Handler public nftHandler;
    RoomHandler private roomHandler;

    event RoomUpdated(uint256 roomLength);
    event NFTOwnerUpdated(address newOwner);

    constructor(
        ERC721Handler _nftHandler,
        uint256 _tokenID,
        uint256 _ethStep,
        uint256 _price,
        address _owner
    ) {
        tokenID = _tokenID;
        ethStep = _ethStep * 1 wei;
        price = _price * 1 wei;
        initBlock = block.number;
        owner = _owner;
        nftHandler = _nftHandler;
        roomHandler = new RoomHandler();

        // initialize handler with this lot’s address
        nftHandler.setLotRoom(address(this));
    }

    modifier onlyWaiting() {
        require(block.number <= initBlock + waitingBlocks, "Not in waiting period");
        _;
    }

    modifier onlyStarted() {
        require(block.number > initBlock + waitingBlocks, "Auction not started");
        _;
    }

    modifier onlyCreator() {
        require(msg.sender == owner, "Not creator");
        _;
    }

    modifier onlySingleParticipant() {
        require(roomHandler.getCountOfMembers() == 1, "Must be single participant");
        _;
    }

    receive() external payable {}

    /// @notice Join the auction
    function raiseHand() external payable onlyWaiting nonReentrant {
        require(msg.value >= deposit, "Insufficient deposit");
        roomHandler.push(msg.sender, msg.value);
        emit RoomUpdated(roomHandler.getCountOfMembers());
    }

    /// @notice Withdraw from auction
    function downHand() external onlyStarted nonReentrant {
        uint256 userDeposit = roomHandler.getDepositFromAddress(msg.sender);
        require(userDeposit > 0, "Not a participant");
        roomHandler.remove(msg.sender);
        payable(msg.sender).transfer(userDeposit);
        if (roomHandler.getCountOfMembers() == 1) {
            finalBlock = block.number - 1;
        }
        emit RoomUpdated(roomHandler.getCountOfMembers());
    }

    /// @notice Update token metadata (e.g., freezing graph)
    function updateTokenData(bytes calldata newData) external onlyCreator {
        nftHandler.appendData(newData);
    }

    /// @notice Finalize purchase
    function buy() external payable onlySingleParticipant nonReentrant {
        uint256 userDeposit = roomHandler.getDepositFromAddress(msg.sender);
        require(userDeposit > 0, "Not eligible");
        require(!nftHandler.isOwner(msg.sender), "Already owner");

        uint256 finalPrice = getFinalPrice();
        if (finalPrice > userDeposit) {
            require(msg.value == finalPrice - userDeposit, "Incorrect payment");
            payable(owner).transfer(finalPrice);
        } else {
            payable(owner).transfer(finalPrice);
            if (userDeposit > finalPrice) {
                payable(msg.sender).transfer(userDeposit - finalPrice);
            }
        }

        nftHandler.transfer(msg.sender);
        emit NFTOwnerUpdated(msg.sender);
    }

    /// @notice Calculate current final price
    function getFinalPrice() public view returns (uint256) {
        uint256 count = roomHandler.getCountOfMembers();
        if (count == 0 || (finalBlock == 0 && count == 1) || block.number < initBlock + waitingBlocks) {
            return price;
        }
        uint256 elapsed = ((finalBlock > 0 ? finalBlock : block.number) - initBlock - waitingBlocks);
        return price + (elapsed / blockStep) * ethStep;
    }

    function getCountOfMembers() external view returns (uint256) {
        return roomHandler.getCountOfMembers();
    }

    function isMember(address user) external view returns (bool) {
        return roomHandler.getDepositFromAddress(user) > 0;
    }

    function isNFTOwner(address user) external view returns (bool) {
        return nftHandler.isOwner(user);
    }

    function isWaiting() external view returns (bool) {
        return block.number < initBlock + waitingBlocks;
    }

    function getLotRoomInfo()
    public
    view
    returns (
        uint256,
        uint256,
        uint256,
        uint256,
        uint256,
        uint256,
        uint256
    )
    {
        return (
            tokenID,
            initBlock,
            getFinalPrice(),
            deposit,
            ethStep,
            waitingBlocks,
            blockStep
        );
    }
}

contracts/RoomHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

// @title Internal deposit manager
contract RoomHandler {
    mapping(address => uint256) private _deposits;
    uint256 private _memberCount;

    function push(address addr, uint256 deposit) external {
        require(_deposits[addr] == 0, "Already in room");
        _deposits[addr] = deposit;
        _memberCount++;
    }

    function remove(address addr) external {
        require(_deposits[addr] != 0, "Not in room");
        delete _deposits[addr];
        _memberCount--;
    }

    function getDepositFromAddress(address addr) external view returns (uint256) {
        return _deposits[addr];
    }

    function getCountOfMembers() external view returns (uint256) {
        return _memberCount;
    }
}

